class score_Type {
    /* Function Objective: Count the scores that reach the pass mark
       Input parameters : i_score_list (integer list) all scores, pass_score (integer) pass mark
       Function description: Walk through the scores and count every score that is at least the pass mark
       Return Value : int number of passed scores
       Created By : Programmer A
       Create Date: 2026-09-28
       Revised By:
       Revised Date:
    */
    static int i_Count_Passed(int[] i_score_list, int pass_score) {
        int i_passed_total = 0;
        // count every score that reaches the pass mark
        for (int i_index = 0; i_index < i_score_list.length; i_index++) {
            // check the score against the pass mark
            if (i_score_list[i_index] >= pass_score) {
                i_passed_total = i_passed_total + 1;
            }
            // else the score is below the pass mark, skip it
            else {
                i_passed_total = i_passed_total + 0;
            }
        }
        return i_passed_total;
    }
}
